-- Runner experience: training programmes, sessions and enrolments.
-- Owner: Runner experience (feat/runner-experience).
--
-- `kind` mirrors the shared ProgrammeKind contract; `category` is a
-- feature-level grouping for the catalogue (Couch to 5K, General fitness,
-- Training and Shine). Session `blocks` follow the WorkoutBlock contract.

create table public.programmes (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique check (slug ~ '^[a-z0-9-]+$'),
  title text not null check (char_length(title) between 1 and 120),
  summary text not null default '' check (char_length(summary) <= 500),
  kind text not null check (kind in ('couch_to_5k', 'strength_conditioning', 'custom')),
  category text not null check (category in ('couch_to_5k', 'general_fitness', 'training_and_shine')),
  level text not null check (level in ('beginner', 'intermediate', 'advanced')),
  duration_weeks integer not null check (duration_weeks between 1 and 52),
  sessions_per_week integer not null check (sessions_per_week between 1 and 7),
  -- 'coach_approval' programmes start as a request a coach approves (future paid tier).
  enrolment text not null default 'open' check (enrolment in ('open', 'coach_approval')),
  published boolean not null default false,
  owner_id uuid references public.profiles (id) on delete set null,
  sort_order integer not null default 100,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create trigger programmes_set_updated_at
  before update on public.programmes
  for each row execute function private.set_updated_at();

create table public.programme_sessions (
  id uuid primary key default gen_random_uuid(),
  programme_id uuid not null references public.programmes (id) on delete cascade,
  week integer not null check (week >= 1),
  -- Suggested day within the week (1 = first day). Gaps are rest days.
  day integer not null check (day between 1 and 7),
  title text not null check (char_length(title) between 1 and 120),
  workout_type text not null
    check (workout_type in ('run', 'walk_run', 'walk', 'strength', 'conditioning', 'mobility', 'cross_training', 'rest')),
  estimated_minutes integer not null check (estimated_minutes > 0),
  blocks jsonb not null default '[]'::jsonb check (jsonb_typeof(blocks) = 'array'),
  instructions text not null default '',
  -- Completing this session completes a milestone (e.g. the last run of a week).
  is_milestone boolean not null default false,
  unique (programme_id, week, day)
);

create index programme_sessions_programme_idx on public.programme_sessions (programme_id, week, day);

create table public.enrollments (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  programme_id uuid not null references public.programmes (id) on delete cascade,
  status text not null default 'active'
    check (status in ('requested', 'active', 'paused', 'completed', 'withdrawn')),
  coach_id uuid references public.profiles (id) on delete set null,
  started_at timestamptz,
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- One open enrolment per runner and programme.
create unique index enrollments_one_open_per_programme
  on public.enrollments (user_id, programme_id)
  where status in ('requested', 'active', 'paused');
create index enrollments_user_idx on public.enrollments (user_id);

create trigger enrollments_set_updated_at
  before update on public.enrollments
  for each row execute function private.set_updated_at();

-- Runners cannot choose their own status: open programmes start active,
-- coach-led programmes start as a request.
create function private.enrollment_initial_status()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  mode text;
begin
  select p.enrolment into mode from public.programmes p where p.id = new.programme_id and p.published;
  if mode is null then
    raise exception 'programme not available' using errcode = '23514';
  end if;
  if mode = 'coach_approval' then
    new.status := 'requested';
    new.started_at := null;
  else
    new.status := 'active';
    new.started_at := coalesce(new.started_at, now());
  end if;
  new.completed_at := null;
  return new;
end;
$$;

create trigger enrollments_initial_status
  before insert on public.enrollments
  for each row execute function private.enrollment_initial_status();

-- ---------------------------------------------------------------------------
-- Grants and RLS
-- ---------------------------------------------------------------------------

revoke all on public.programmes, public.programme_sessions, public.enrollments from anon, authenticated;

grant select on public.programmes, public.programme_sessions to anon, authenticated;
grant insert, update, delete on public.programmes, public.programme_sessions to authenticated;
grant select, insert on public.enrollments to authenticated;
grant update (status) on public.enrollments to authenticated;

alter table public.programmes enable row level security;
alter table public.programme_sessions enable row level security;
alter table public.enrollments enable row level security;

create policy "programmes: anyone reads published"
  on public.programmes for select to anon, authenticated
  using (published);

create policy "programmes: managers read all"
  on public.programmes for select to authenticated
  using ((select private.has_role('programme_manager')) or (select private.has_role('admin')));

create policy "programmes: managers write"
  on public.programmes for all to authenticated
  using ((select private.has_role('programme_manager')) or (select private.has_role('admin')))
  with check ((select private.has_role('programme_manager')) or (select private.has_role('admin')));

create policy "programme_sessions: read with published programme"
  on public.programme_sessions for select to anon, authenticated
  using (exists (select 1 from public.programmes p where p.id = programme_id and p.published));

create policy "programme_sessions: managers write"
  on public.programme_sessions for all to authenticated
  using ((select private.has_role('programme_manager')) or (select private.has_role('admin')))
  with check ((select private.has_role('programme_manager')) or (select private.has_role('admin')));

create policy "enrollments: read own"
  on public.enrollments for select to authenticated
  using ((select auth.uid()) = user_id);

create policy "enrollments: staff read"
  on public.enrollments for select to authenticated
  using ((select private.is_staff()));

create policy "enrollments: enrol self"
  on public.enrollments for insert to authenticated
  with check ((select auth.uid()) = user_id);

-- Runners may only pause or withdraw their own enrolment. Completion and
-- approval are server-side (secret key) or staff actions.
create policy "enrollments: pause or withdraw own"
  on public.enrollments for update to authenticated
  using ((select auth.uid()) = user_id and status in ('requested', 'active', 'paused'))
  with check ((select auth.uid()) = user_id and status in ('paused', 'withdrawn', 'active'));

create function private.enrollment_guard_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- A runner cannot self-approve a coach-led request.
  if old.status = 'requested' and new.status = 'active' then
    if current_user in ('service_role', 'postgres') then
      return new;
    end if;
    if not private.is_staff() then
      raise exception 'enrolment requires coach approval' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;

create trigger enrollments_guard_update
  before update on public.enrollments
  for each row execute function private.enrollment_guard_update();

